static const struct { const char* name; const unsigned char* data; size_t size; const char* from; } kTemplates[] = {
    {"project", k_project, sizeof k_project, "a sample project: the whole project (its media and tracks are not used)"},
    {"videoTrack", k_videoTrack, sizeof k_videoTrack, "a sample project: its video track"},
    {"audioTrack", k_audioTrack, sizeof k_audioTrack, "a sample project: its audio track"},
    {"fx", k_fx, sizeof k_fx, "a sample project: an OpenFX effect (Brightness and Contrast)"},
    {"panCrop", k_panCrop, sizeof k_panCrop, "a sample project: an event pan/crop"},
    {"mediaAV", k_mediaAV, sizeof k_mediaAV, "a sample project: a video file with sound (.mp4)"},
    {"mediaVideo", k_mediaVideo, sizeof k_mediaVideo, "a sample project: a picture (.jpg)"},
    {"mediaAudio", k_mediaAudio, sizeof k_mediaAudio, "a sample project: a sound file (.mp3)"},
    {"mediaVeg", k_mediaVeg, sizeof k_mediaVeg, "a sample project: another VEGAS project used as media"},
    {"mediaSubclip", k_mediaSubclip, sizeof k_mediaSubclip, "a sample project: a subclip"},
    {"mediaGenerated", k_mediaGenerated, sizeof k_mediaGenerated, "a sample project: generated media (Titles & Text)"},
    {"eventAudioChain", k_eventAudioChain, sizeof k_eventAudioChain, "a sample project: the audio effects of an event (one VST plug-in)"},
    {"trackAudioChain", k_trackAudioChain, sizeof k_trackAudioChain, "a sample project: the audio effects of a track"},
    {"trackEnvelopes", k_trackEnvelopes, sizeof k_trackEnvelopes, "a sample project: a track volume envelope (4 points)"},
    {"eventEnvelopes", k_eventEnvelopes, sizeof k_eventEnvelopes, "a sample project: an event velocity envelope (1 point)"},
    {"marker", k_marker, sizeof k_marker, "a sample project: a marker"},
    {"group", k_group, sizeof k_group, "a sample project: a group of two events"},
    {"bus", k_bus, sizeof k_bus, "a sample project: an audio bus (Bus A) without effects"},
};

std::string templateBytes(const char* name)
{
    for (const auto& t : kTemplates)
        if (std::strcmp(t.name, name) == 0) return std::string((const char*)t.data, t.size);
    return std::string();
}

